import{_ as a,o as d,c as e,a2 as i}from"./chunks/framework.BW2T23B9.js";const b=JSON.parse('{"title":"教材导入","description":"","frontmatter":{},"headers":[],"relativePath":"authoring/textbook-import.md","filePath":"authoring/textbook-import.md","lastUpdated":null}'),r={name:"authoring/textbook-import.md"};function l(o,t,h,n,c,s){return d(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="教材导入" tabindex="-1">教材导入 <a class="header-anchor" href="#教材导入" aria-label="Permalink to &quot;教材导入&quot;">​</a></h1><p>教材导入是半自动课程生产流程。模型负责抽取和生成草稿；课程作者负责审校、冲突处理、验证与发布。</p><h2 id="支持输入" tabindex="-1">支持输入 <a class="header-anchor" href="#支持输入" aria-label="Permalink to &quot;支持输入&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>支持范围</th></tr></thead><tbody><tr><td>Markdown / 文本</td><td>UTF-8，按标题切章</td></tr><tr><td>PDF</td><td>文本原生 PDF；扫描 PDF 不承诺 OCR</td></tr><tr><td>Word</td><td><code>.doc</code> / <code>.docx</code>，需要 python-docx</td></tr><tr><td>图片</td><td>作为 vision 附件；取决于所配置模型</td></tr></tbody></table><p>源文件保留在作者控制的位置。项目文件只保存引用与抽取结果，不复制源文件本体。</p><h2 id="工作区" tabindex="-1">工作区 <a class="header-anchor" href="#工作区" aria-label="Permalink to &quot;工作区&quot;">​</a></h2><p>课程工坊由项目库和三栏创作画布组成：</p><ul><li>左栏：教材、章节、知识点审校与资源池。</li><li>中栏：AI 轨道、主题、级别、模板与生成控制。</li><li>右栏：结构大纲、草稿、diff、局部重生成和导入。</li></ul><p>项目保存到 <code>tool/gui/var/textbooks/{project_id}/project.json</code>，允许中断后恢复。</p><h2 id="流程" tabindex="-1">流程 <a class="header-anchor" href="#流程" aria-label="Permalink to &quot;流程&quot;">​</a></h2><ol><li>选择文件并提取文本。</li><li>按章节切分。</li><li>选择教材预设与并发数。</li><li>抽取词汇、表达、语法点和对话。</li><li>处理红色错误和黄色警告。</li><li>将确认资源加入资源池。</li><li>生成 Section 与 Lesson 草稿。</li><li>查看结构、覆盖率和 JSON diff。</li><li>选择冲突策略。</li><li>导入到内存课程项目。</li><li>手动保存并运行 validate、lint。</li></ol><h2 id="预设" tabindex="-1">预设 <a class="header-anchor" href="#预设" aria-label="Permalink to &quot;预设&quot;">​</a></h2><table tabindex="0"><thead><tr><th>预设</th><th>目标</th><th>默认倾向</th></tr></thead><tbody><tr><td>general</td><td>通用教材</td><td>均衡抽取</td></tr><tr><td>grammar</td><td>语法书</td><td>低温度、强调规则</td></tr><tr><td>dialogue</td><td>对话书</td><td>强调表达与口语</td></tr><tr><td>reading</td><td>阅读材料</td><td>以词汇抽取为主</td></tr></tbody></table><p>预设影响抽取参数，不免除审校。</p><h2 id="冲突策略" tabindex="-1">冲突策略 <a class="header-anchor" href="#冲突策略" aria-label="Permalink to &quot;冲突策略&quot;">​</a></h2><table tabindex="0"><thead><tr><th>策略</th><th>行为</th></tr></thead><tbody><tr><td>合并预览</td><td>显示差异并逐项决定，默认</td></tr><tr><td>跳过已存在</td><td>保留现有 Section</td></tr><tr><td>覆盖已存在</td><td>整体替换，风险最高</td></tr><tr><td>作为新 Section</td><td>生成新 ID 后并存</td></tr></tbody></table><h2 id="去重" tabindex="-1">去重 <a class="header-anchor" href="#去重" aria-label="Permalink to &quot;去重&quot;">​</a></h2><p>项目内相同知识点统一到首次 ID；与现有课程碰撞时可以对齐已有 ID。自动去重依据规范化 key，作者必须检查同形异义和释义冲突。</p><h2 id="失败处理" tabindex="-1">失败处理 <a class="header-anchor" href="#失败处理" aria-label="Permalink to &quot;失败处理&quot;">​</a></h2><ul><li>未切章：检查 Markdown 标题层级。</li><li>PDF 无文本：在外部完成 OCR 并转为 Markdown。</li><li>单章抽取失败：重试、仅抽词汇或跳过。</li><li>JSON 不通过：返回草稿修复，不直接覆盖课程。</li><li>价格未知：只显示 Token，不生成误导性成本。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/docs/guide/editor">课程编辑器</a></li><li><a href="/docs/authoring/resource-files">资源文件</a></li><li><a href="/docs/authoring/validation">校验与 Lint</a></li></ul>',22)])])}const p=a(r,[["render",l]]);export{b as __pageData,p as default};
